def factorial(n):
    if n == 1:
        return 1
    return n * factorial(n - 1)

print(factorial(4))

def total(n):
    if n == 0:
        return 0
    return n + total(n - 1)

print(total(4))

def length(s):
    if s == "":
        return 0
    return 1 + length(s[1:])

print(length("code"))

def rev(s):
    if len(s) <= 1:
        return s
    return rev(s[1:]) + s[0]

print(rev("abc"))

